#!/usr/bin/env python3
"""Turn the boot stub binary into NEORV32's neorv32_bootrom_image package.

usage: bootrom_vhd.py boot.bin neorv32_bootrom_image.vhd
"""
import struct
import sys

data = open(sys.argv[1], "rb").read()
data += b"\0" * (-len(data) % 4)
words = struct.unpack("<%dI" % (len(data) // 4), data)
lines = [
    "-- Generated by CORE/modem-fw/tools/bootrom_vhd.py from CORE/modem-fw/boot/boot.S. Do not edit.",
    "library ieee;",
    "use ieee.std_logic_1164.all;",
    "",
    "package neorv32_bootrom_image is",
    "",
    "type rom_t is array (0 to 1023) of std_ulogic_vector(31 downto 0);",
    "constant image_size_c : natural := %d;" % len(data),
    "constant image_data_c : rom_t := (",
]
lines += ['x"%08x",' % w for w in words]
lines += ["others => (others => '0')", ");", "", "end package;", ""]
open(sys.argv[2], "w").write("\n".join(lines))
